/**
 * Unit tests for XmlSerializerProvider._rootNameFromConfig().
 * Since the method is protected, we use a Test subclass to access it.
 */
public class XmlSerializerProvider__rootNameFromConfig_TriageGen0Test {

    @Mock
    private XmlRootNameLookup _rootNames;

    @Mock
    private SerializationConfig _config;

    @Mock
    private PropertyName _propertyName;

    private TestableXmlSerializerProvider _provider;

    /**
     * Subclass to expose the protected method for testing.
     */
    private static class TestableXmlSerializerProvider extends XmlSerializerProvider {
        public TestableXmlSerializerProvider(XmlRootNameLookup rootNames, SerializationConfig config) {
            super(rootNames);
            // Note: In real Jackson code, _config is a field in the base class.
            // We rely on the fact that we can inject a mocked config via reflection or 
            // by the way the provider is constructed if it were a public field.
            // Since we cannot change the source, we assume the test setup can bridge this.
        }

        // Expose the protected method
        public QName call_rootNameFromConfig() {
            return _rootNameFromConfig();
        }

        // Helper to inject the mock config into the protected field of the provider
        public void setConfig(SerializationConfig config) {
            try {
                java.lang.reflect.Field field = XmlSerializerProvider.class.getDeclaredField("_config");
                field.setAccessible(true);
                field.set(this, config);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
    }

    // Mocking PropertyName interface/class as it is used in the method
    // Assuming PropertyName is an interface or class available in the classpath
    public interface PropertyName {
        String getNamespace();
        String getSimpleName();
    }

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        _provider = new TestableXmlSerializerProvider(_rootNames, _config);
        _provider.setConfig(_config);
    }

    @Test
    public void test_rootNameFromConfig_returnsNullWhenNameIsNull() {
        when(_config.getFullRootName()).thenReturn(null);

        QName result = _provider.call_rootNameFromConfig();

        assertNull(result);
    }

    @Test
    public void test_rootNameFromConfig_returnsQNameWithoutNamespaceWhenNamespaceIsEmpty() {
        when(_config.getFullRootName()).thenReturn(_propertyName);
        when(_propertyName.getNamespace()).thenReturn("");
        when(_propertyName.getSimpleName()).thenReturn("root");

        QName result = _provider.call_rootNameFromConfig();

        assertEquals(new QName("root"), result);
    }

    @Test
    public void test_rootNameFromConfig_returnsQNameWithoutNamespaceWhenNamespaceIsNull() {
        when(_config.getFullRootName()).thenReturn(_propertyName);
        when(_propertyName.getNamespace()).thenReturn(null);
        when(_propertyName.getSimpleName()).thenReturn("root");

        QName result = _provider.call_rootNameFromConfig();

        assertEquals(new QName("root"), result);
    }

    @Test
    public void test_rootNameFromConfig_returnsQNameWithNamespace() {
        String ns = "http://example.com";
        String localName = "root";
        when(_config.getFullRootName()).thenReturn(_propertyName);
        when(_propertyName.getNamespace()).thenReturn(ns);
        when(_propertyName.getSimpleName()).thenReturn(localName);

        QName result = _provider.call_rootNameFromConfig();

        assertEquals(new QName(ns, localName), result);
    }
}
